import manifest from '../data/image-manifest.json';

interface ImageEntry {
  widths: number[];
  width: number;
  height: number;
}

const entries = manifest as Record<string, ImageEntry>;

/**
 * Returns src, srcSet and intrinsic size for an image generated by
 * scripts/process_images.py. Paths stay relative so the build works in any folder.
 */
export function imageSet(base: string) {
  const entry = entries[base];
  if (!entry) {
    if (import.meta.env.DEV) console.warn(`[images] "${base}" is not in image-manifest.json. Run npm run images.`);
    return { src: `${base}.webp`, srcSet: undefined, width: undefined, height: undefined };
  }
  const srcSet = entry.widths.map((w) => `${base}-${w}.webp ${w}w`).join(', ');
  const fallback = entry.widths[Math.min(1, entry.widths.length - 1)];
  return { src: `${base}-${fallback}.webp`, srcSet, width: entry.width, height: entry.height };
}

export function formatDate(iso: string, style: 'long' | 'stamp' = 'long') {
  const [y, m, d] = iso.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  if (style === 'stamp') {
    return `${String(d).padStart(2, '0')}.${String(m).padStart(2, '0')}.${y}`;
  }
  return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
}
